import{_ as p,a0 as o,w as r,s as d,I as s,x as e,a1 as i,A as l,ao as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const c=JSON.parse('{"title":"如何安装和使用 GNOME Boxes 来创建虚拟机 | LCTT x X-CMD","titleTemplate":false,"description":"如何安装和使用 GNOME Boxes 来创建虚拟机 | LCTT (202306) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何安装和使用 GNOME Boxes 来创建虚拟机 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何安装和使用 GNOME Boxes 来创建虚拟机 | LCTT (202306) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202306/20220922 How to Install and Use GNOME Boxes to Create Virtual Machines","title":"如何安装和使用 GNOME Boxes 来创建虚拟机","tag":"202306","desc":""},"relativePath":"202306/20220922 How to Install and Use GNOME Boxes to Create Virtual Machines.md","filePath":"[post].md"}'),u={name:"202306/20220922 How to Install and Use GNOME Boxes to Create Virtual Machines.md"};function g(h,t,b,m,k,x){const a=o("Link");return r(),d("div",null,[t[26]||(t[26]=s("h1",{id:"如何安装和使用-gnome-boxes-来创建虚拟机",tabindex:"-1"},[e("如何安装和使用 GNOME Boxes 来创建虚拟机 "),s("a",{class:"header-anchor",href:"#如何安装和使用-gnome-boxes-来创建虚拟机","aria-label":"Permalink to “如何安装和使用 GNOME Boxes 来创建虚拟机”"},"​")],-1)),t[27]||(t[27]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202306/28/151813xrp87wpccdclwc3c.jpg",alt:""})],-1)),t[28]||(t[28]=s("blockquote",null,[s("p",null,"本快速教程解释了安装和使用 GNOME Boxes 以及创建虚拟机的步骤，以及一些提示和故障排除。")],-1)),t[29]||(t[29]=s("p",null,"虚拟化是使用抽象硬件层运行虚拟实例（而不是实际实例）的过程。通俗地说，它允许你同时安装和运行多个操作系统（Linux、Windows）。",-1)),s("p",null,[i(a,{href:"https://www.redhat.com/en/topics/virtualization/what-is-a-virtual-machine"},{default:l(()=>[...t[0]||(t[0]=[e("虚拟机",-1)])]),_:1}),t[1]||(t[1]=e(" 是一个模拟操作系统，它运行在另一个操作系统之上，并使用与主机相同的硬件和存储空间。虽然，你可以控制可以分配给虚拟机的共享内存或空间量。",-1))]),s("p",null,[t[3]||(t[3]=e("有多种软件可用于创建虚拟机，例如 ",-1)),i(a,{href:"https://www.debugpoint.com/tag/virtualbox/"},{default:l(()=>[...t[2]||(t[2]=[e("Virtual Box",-1)])]),_:1}),t[4]||(t[4]=e("、KVM、Hyper-V、VMWare player 和 GNOME Boxes。",-1))]),s("p",null,[t[6]||(t[6]=e("但老实说，它们中的大多数使用起来都很复杂，有时还不够稳定。",-1)),i(a,{href:"https://wiki.gnome.org/Apps/Boxes"},{default:l(()=>[...t[5]||(t[5]=[e("GNOME Boxes",-1)])]),_:1}),t[7]||(t[7]=e(" 是另一个自由开源的软件，它非常易于使用，通过抽象出大量选项让你可以轻松创建和管理虚拟机。",-1))]),t[30]||(t[30]=n('<h3 id="安装-gnome-boxes" tabindex="-1">安装 GNOME Boxes <a class="header-anchor" href="#安装-gnome-boxes" aria-label="Permalink to “安装 GNOME Boxes”">​</a></h3><p>如果你正在运行 Fedora 的 GNOME 定制版，你应该已经安装了它。但是，对于 Ubuntu、Linux Mint、Kubuntu 和其他发行版，你只需运行以下命令即可将其安装到你的系统中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install gnome-boxes</span></span></code></pre></div><h4 id="通过-flatpak" tabindex="-1">通过 Flatpak <a class="header-anchor" href="#通过-flatpak" aria-label="Permalink to “通过 Flatpak”">​</a></h4>',4)),s("p",null,[t[9]||(t[9]=e("它也可以通过 Flatpak 包获得。我会推荐你使用这个版本。首先，使用 ",-1)),i(a,{href:"https://www.debugpoint.com/how-to-install-flatpak-apps-ubuntu-linux/"},{default:l(()=>[...t[8]||(t[8]=[e("本指南",-1)])]),_:1}),t[10]||(t[10]=e(" 在系统中安装 Flatpak，然后从终端运行以下命令进行安装。",-1))]),t[31]||(t[31]=n('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flatpak install flathub org.gnome.Boxes</span></span></code></pre></div><h3 id="使用-gnome-boxes-创建虚拟机" tabindex="-1">使用 GNOME Boxes 创建虚拟机 <a class="header-anchor" href="#使用-gnome-boxes-创建虚拟机" aria-label="Permalink to “使用 GNOME Boxes 创建虚拟机”">​</a></h3><p>从应用菜单启动 GNOME Boxes。</p><p>要创建虚拟机，你需要要虚拟化的操作系统的镜像（*.ISO）。</p><p>你可以从发行版的官方下载页面下载任何操作系统 ISO 镜像。对于本指南，我使用的是 Pop!_OS，这是一个优秀的 Linux 发行版。</p><p>启动后，单击顶部的 “+” 图标启动并选择“<ruby>创建虚拟机<rt>Create a virtual machine</rt></ruby>”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/05/Create-Virtual-Machine.png" alt="Create Virtual Machine"></p><p>在下一个窗口中，你可以选择已经可用的下载，或者你可以选择你的 ISO 文件作为操作系统源。单击“<ruby>操作系统镜像文件<rt>Operating system image file</rt></ruby>”并选择你的 ISO 文件。</p><p>分配虚拟机的内存和存储空间。请记住，你的虚拟机将从主机系统获取内存和存储空间。所以尽量不要分配为最大值。</p><p>例如，在下图中，我从主机系统的 8GB 总内存中为虚拟机（客户机）分配了 2GB 内存。</p><p>同样，如果你只是想测试操作系统，也请选择最小存储空间。但是，如果你正在为服务器或严肃的工作创建虚拟机，请合理分配你要分配的空间或内存量。</p><p>另一件需要记住的重要事情是，除非你删除虚拟机，否则你允许的存储磁盘空间将被永久占用。因此，即使你的虚拟机没有使用整个分配的空间，你也不会获得那么多的可用磁盘空间。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/05/Allocate-resources-for-your-virtual-machine.png" alt="Allocate resources for your virtual machine"></p><p>继续安装。</p><p>在分区窗口中，你应该看到一个硬盘和一个分区，这就是虚拟机的磁盘空间。通常，它们被命名为 <code>/dev/vda</code> 或者 <code>/dev/sda</code>。</p><p>不用担心；你可以随意使用此分区，这不会影响你的物理磁盘分区或实际主机系统上的任何数据。安装 Linux 时遵循相同的 <code>/root</code> 分区，然后继续。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/05/Virtual-machine-partition.png" alt="Virtual machine partition"></p><p>完成安装后，你应该会在虚拟机中看到新的操作系统。在 GNOME Boxes 中，你应该会看到一个系统条目。你可以单击它启动虚拟机。</p><p>你可以使用虚拟机操作系统的内部关闭选项关闭虚拟机。</p><p>如果需要，你还可以通过选择上下文菜单选项来删除虚拟机。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/05/Context-menu-in-installed-virtual-machine.png" alt="Context menu in installed virtual machine"></p><p>你还可以从属性窗口检查你的虚拟机使用了多少内存和 CPU。</p><p>请注意，你可以使用属性调整现有虚拟机的内存和其他项目。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/05/System-properties.png" alt="System properties"></p><h3 id="故障排除" tabindex="-1">故障排除 <a class="header-anchor" href="#故障排除" aria-label="Permalink to “故障排除”">​</a></h3><p>以下是你在使用 GNOME Boxes 时可能遇到的一些常见错误或问题。</p><h4 id="_1、虚拟机中的分辨率问题" tabindex="-1">1、虚拟机中的分辨率问题 <a class="header-anchor" href="#_1、虚拟机中的分辨率问题" aria-label="Permalink to “1、虚拟机中的分辨率问题”">​</a></h4><p>如果你的虚拟机分辨率很低，这与你的主机系统不兼容，那么你必须安装以下项目。在客户系统（而不是主机系统）中打开终端并运行以下命令。</p><p>对于基于 Ubuntu 的发行版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install spice-vdagent spice-webdavd</span></span></code></pre></div><p>对于 Fedora 系统：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install spice-vdagent spice-webdavd</span></span></code></pre></div><p>这两个包有助于确定合适的分辨率、在主机和客户之间复制/粘贴、通过公共文件夹共享文件等。</p><p>安装后，重新启动客户系统；或者你可以在重启后注销并重新登录一次，你应该会看到正确的分辨率。</p><h4 id="_2、在-ubuntu-18-04-中-gnome-boxes-不能启动虚拟机" tabindex="-1">2、在 Ubuntu 18.04 中 GNOME Boxes 不能启动虚拟机 <a class="header-anchor" href="#_2、在-ubuntu-18-04-中-gnome-boxes-不能启动虚拟机" aria-label="Permalink to “2、在 Ubuntu 18.04 中 GNOME Boxes 不能启动虚拟机”">​</a></h4><p>如果你在 Boxes 3.34 中创建虚拟机，那么你应该知道有一个错误导致你的虚拟机无法启动。要解决这个问题，你必须执行一些额外的步骤。请记住，最新的 Boxes 3.36 不需要这些。</p><p>打开终端窗口并运行以下命令来更改 qemu 配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo gedit /etc/modprobe.d/qemu-system-x86.conf</span></span></code></pre></div><p>在上面的文件中添加以下行并保存：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>group=kvm</span></span></code></pre></div><p>现在，运行以下命令将你的用户名添加到 KVM 组。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo usermod -a -G kvm &lt;你的帐户名称&gt;</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>在本文中，你了解了如何安装和使用 GNOME Boxes 来利用虚拟化。我希望它能帮助你。</p><p>🗨️ 如果你遇到任何错误或对 GNOME Boxes 的虚拟机有任何疑问，请使用下面的评论栏告诉我。</p><p><em>（题图：MJ/b4d091cf-9585-468b-9ce6-ba0b0c69cce4）</em></p><hr>',47)),s("p",null,[t[12]||(t[12]=e("via: ",-1)),i(a,{href:"https://www.debugpoint.com/install-use-gnome-boxes/"},{default:l(()=>[...t[11]||(t[11]=[e("https://www.debugpoint.com/install-use-gnome-boxes/",-1)])]),_:1})]),s("p",null,[t[17]||(t[17]=e("作者：",-1)),i(a,{href:"https://www.debugpoint.com/author/admin1/"},{default:l(()=>[...t[13]||(t[13]=[e("Arindam",-1)])]),_:1}),t[18]||(t[18]=e(" 选题：",-1)),i(a,{href:"https://github.com/lkxed"},{default:l(()=>[...t[14]||(t[14]=[e("lkxed",-1)])]),_:1}),t[19]||(t[19]=e(" 译者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:l(()=>[...t[15]||(t[15]=[e("geekpi",-1)])]),_:1}),t[20]||(t[20]=e(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:l(()=>[...t[16]||(t[16]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[23]||(t[23]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[21]||(t[21]=[e("LCTT",-1)])]),_:1}),t[24]||(t[24]=e(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:l(()=>[...t[22]||(t[22]=[e("Linux中国",-1)])]),_:1}),t[25]||(t[25]=e(" 荣誉推出",-1))])])}const C=p(u,[["render",g]]);export{c as __pageData,C as default};
